```rust
fn parse_rows(value: Option<&Value>, path: &str) -> Result<Vec<(String, Value)>, ApiError> {
    let value = value.ok_or_else(|| ApiError::bad_request("missing required field", path))?;
    let arr = value.as_array().ok_or_else(|| ApiError::bad_request("expected an array of rows", path))?;
    let mut rows = Vec::with_capacity(arr.len());
    for (i, item) in arr.iter().enumerate() {
        let ipath = format!("{path}/{i}");
        let obj = item.as_object().ok_or_else(|| ApiError::bad_request("row must be an object", &ipath))?;
        let id = obj.get("id").and_then(Value::as_str).ok_or_else(|| ApiError::bad_request("row id must be a string", format!("{ipath}/id")))?;
        if id.is_empty() { return Err(ApiError::bad_request("row id must be non-empty", format!("{ipath}/id"))); }
        let values = obj.get("values").ok_or_else(|| ... "{ipath}/values")?;
        if !values.is_object() { return Err(... "values must be an object"); }
        rows.push((id.to_owned(), values.clone()));
    }
    // uniqueness
    rows.sort_by(|a,b| a.0.cmp(&b.0));
    for w in rows.windows(2) { if w[0].0 == w[1].0 { return Err(ApiError::bad_request(format!("duplicate row id {:?}", w[0].0), path)); } }
    Ok(rows)
}
```

