fn escape_segment(seg: &str) -> String { seg.replace('~', "~0").replace('/', "~1") }

fn parse_pointer(path: &str) -> Result<Vec<String>, ()> {
    // must start with '/'
    if path.is_empty() { return Err(()); }  // 顶层空指针不允许
    if !path.starts_with('/') { return Err(()); }
    let mut segs = Vec::new();
    for raw in path[1..].split('/') {
        let mut seg = String::new();
        let mut chars = raw.chars();
        while let Some(c) = chars.next() {
            if c == '~' {
                match chars.next() {
                    Some('0') => seg.push('~'),
                    Some('1') => seg.push('/'),
                    _ => return Err(()),
                }
            } else { seg.push(c); }
        }
        segs.push(seg);
    }
    Ok(segs)
}
```

