fn field_to_json(f: &Field) -> Value {
    let mut m = Map::new();
    m.insert("path", f.path.clone().into());
    if let Some(o) = &f.old { m.insert("old", o.clone()); }
    if let Some(n) = &f.new { m.insert("new", n.clone()); }
