```rust
fn diff_value(path: &str, old: Option<&Value>, new: Option<&Value>, out: &mut Vec<Field>) {
    match (old, new) {
        (Some(Value::Object(o)), Some(Value::Object(n))) => {
            for (k, v) in o {
                let p = format!("{path}/{}", escape_segment(k));
                match n.get(k) {
                    Some(nv) => diff_value(&p, Some(v), Some(nv), out),
                    None => out.push(Field { path: p, old: Some(v.clone()), new: None }),
                }
            }
            for (k, v) in n {
                if !o.contains_key(k) {
                    out.push(Field { path: format!("{path}/{}", escape_segment(k)), old: None, new: Some(v.clone()) });
                }
            }
        }
        (o, n) => {
            let equal = match (o, n) {
                (Some(a), Some(b)) => json_eq(a, b),
                (None, None) => true,
                _ => false,
            };
            if !equal {
                out.push(Field { path: path.to_owned(), old: o.cloned(), new: n.cloned() });
            }
        }
    }
}
```

Note: at top level, values are both objects so path "" never emitted for a field (fields always have ≥1 segment). Good.

