    let reverse = match direction { "forward" => false, "reverse" => true, _ => return Err(...) };
    let changes_val = obj.get("changes").ok_or(..."/changes")?;
    let arr = as array;
    let mut changes = Vec::new();
    for (i, c) in arr.iter().enumerate() { changes.push(parse_change(c, &format!("/changes/{i}"))?); }
    // duplicate ids across changes
