fn validate_change(map, change, reverse, cpath) -> Result<(), ApiError> {
    match change {
        Add { id, value } => {
            let exists = map.contains_key(id);
            if !reverse {
                if exists { return Err(conflict("row already exists", cpath/id?)); }
            } else {
                match map.get(id) {
                    None => Err(conflict("row to remove does not exist", ...)),
                    Some(v) if !json_eq(v, value) => Err(conflict("row values do not match expected value", "{cpath}/value")),
                    _ => Ok(())
                }
            }
        }
        Remove { id, value } => mirror,
        Update { id, fields } => {
            let row = map.get(id).ok_or_else(|| conflict("row does not exist", format!("{cpath}/id")))?;
            for (fi, f) in fields.iter().enumerate() {
                let fpath = format!("{cpath}/fields/{fi}");
                let expected = if reverse { &f.new } else { &f.old };
                let segs = parse_pointer(&f.path).unwrap(); // already validated
                let current = get_path(row, &segs);
                match (expected, current) {
                    (None, None) => {}
                    (Some(e), Some(c)) if json_eq(e, c) => {}
                    (None, Some(_)) => return Err(conflict("expected field to be absent", format!("{fpath}"))),
                    (Some(_), None) => Err(conflict("expected value but field is missing", ...)),
                    _ => Err(conflict("value mismatch", format!("{fpath}/old" or "/new"))),
                }
            }
        }
    }
}
