//! 无状态快照差异（diff）与双向回放（apply）的核心逻辑。
//!
//! 模块只接收和返回 `serde_json::Value`，不感知 HTTP；
//! HTTP 层仅负责 JSON 解析与状态码映射。

use serde_json::{Map, Number, Value};

/// 业务错误。`status` 为 HTTP 状态码，`path` 定位请求体中的出错字段。
#[derive(Debug)]
pub struct ApiError {
    pub status: u16,
    pub code: &'static str,
    pub message: String,
    pub path: String,
}

impl ApiError {
    pub fn bad_request(message: impl Into<String>, path: impl Into<String>) -> Self {
        Self { status: 400, code: "bad_request", message: message.into(), path: path.into() }
    }

    pub fn conflict(message: impl Into<String>, path: impl Into<String>) -> Self {
        Self { status: 409, code: "conflict", message: message.into(), path: path.into() }
    }
}

/// 对象字段差异：`old`/`new` 为 `None` 表示该侧字段缺失（与 JSON null 区分）。
#[derive(Debug, Clone, PartialEq)]
struct Field {
    path: String,
    old: Option<Value>,
    new: Option<Value>,
}

#[derive(Debug)]
enum Change {
    Add { id: String, value: Value },
    Remove { id: String, value: Value },
    Update { id: String, fields: Vec<Field> },
}

impl Change {
    fn id(&self) -> &str {
        match self {
            Change::Add { id, .. } | Change::Remove { id, .. } | Change::Update { id, .. } => id,
        }
    }
}
