fn validate_change(rows: &BTreeMap<String, Value>, change: &Change, reverse: bool, cpath: &str) -> Result<(), ApiError> {
    match change {
        Change::Add { id, value } => {
            if reverse {
                expect_row(rows, id, value, cpath)
            } else if rows.contains_key(id) {
                Err(ApiError::conflict(format!("row {id:?} already exists"), format!("{cpath}/id")))
            } else { Ok(()) }
        }
        Change::Remove { id, value } => {
            if reverse {
                if rows.contains_key(id) { Err(conflict already exists) } else { Ok(()) }
            } else {
                expect_row(rows, id, value, cpath)
            }
        }
        Change::Update { id, fields } => {
            let row = rows.get(id).ok_or_else(|| ApiError::conflict(format!("row {id:?} does not exist"), format!("{cpath}/id")))?;
            for (i, field) in fields.iter().enumerate() {
                validate_field(row, field, reverse, &format!("{cpath}/fields/{i}"))?;
            }
            Ok(())
        }
    }
}

fn expect_row(rows: &BTreeMap<String, Value>, id: &str, value: &Value, cpath: &str) -> Result<(), ApiError> {
    match rows.get(id) {
        None => Err(ApiError::conflict(format!("row {id:?} does not exist"), format!("{cpath}/id"))),
        Some(current) if !json_eq(current, value) => Err(ApiError::conflict(format!("row {id:?} values do not match expected value"), format!("{cpath}/value"))),
        _ => Ok(()),
    }
}
