fn validate_field(row: &Value, field: &Field, reverse: bool, fpath: &str) -> Result<(), ApiError> {
    let segs = parse_pointer(&field.path).expect("field path validated at parse time");
    let expected = if reverse { &field.new } else { &field.old };
    let current = get_path(row, &segs);
    match (expected, current) {
        (None, None) => {}
        (Some(e), Some(c)) if json_eq(e, c) => {}
        (None, Some(_)) => {
            return Err(ApiError::conflict("expected field to be absent but it exists", fpath.to_owned()));
        }
        (Some(_), None) => {
            let side = if reverse { "new" } else { "old" };
            return Err(ApiError::conflict("expected value but field is missing", format!("{fpath}/{side}")));
        }
        (Some(_), Some(_)) => {
            let side = if reverse { "new" } else { "old" };
            return Err(ApiError::conflict("field value does not match expected value", format!("{fpath}/{side}")));
        }
    }
    let target = if reverse { &field.old } else { &field.new };
    if target.is_some() && !parent_is_object(row, &segs) {
        return Err(ApiError::conflict("parent path does not exist or is not an object", format!("{fpath}/path")));
    }
    Ok(())
}
